o_nome="'.MODULO.'"				AND				objeto_id="'.$marca_id.'"				and 				removido=0			ORDER BY 				RENOVACAO_REL ASC			';	$rs->db_open($db_link, $DB_name, $sql);	if(!$rs->EOF())	{		while(!$rs->EOF())		{						$averbamento_id = ''; $DE = ''; $PARA = '';$COM_DE = ''; $COM_PARA = '';	$DATA_BOLETIM = '';$NUMERO_BOLETIM = '';$BOLETIM_EXT = '';$REL = '';						$averbamento_id = $rs->db_data['averbamento_id'];			$DE = $rs->db_data['DE'];			$PARA = $rs->db_data['PARA'];			$COM_DE = $rs->db_data['COM_DE'];			$COM_PARA = $rs->db_data['COM_PARA'];			$DATA_BOLETIM = $rs->db_data['DATA_BOLETIM'];			if($DATA_BOLETIM=='0000-00-00') $DATA_BOLETIM = '';			$NUMERO_BOLETIM = $rs->db_data['NUMERO_BOLETIM'];						$BOLETIM_EXT = $rs->db_data['BOLETIM_EXT'];			$REL = $rs->db_data['RENOVACAO_REL'];			?>				<table width="100%" cellpadding="0" cellspacing="0" border="0" id="LICENSA<?php echo $REL?>">			<tr><td colspan="2">&nbsp;<input type="hidden" value="<?php echo $REL?>;<?php echo $averbamento_id?>;LICENSA" name="LICENSA_ID[]" id="LICENSA_ID<?php echo $REL?>" class="LICENSA_ID" /></td></tr>			<tr>									<td align="left">De:</td>			<td><input type="text" class="form-control" name="LICENSA_DE<?php echo $REL?>" id="LICENSA_DE<?php echo $REL?>" value="<?php echo $DE?>" /></td>			<td rowspan="10" valign="top"><a href="#" onclick="remove_averbamento('<?php echo $REL?>')"><img src="img/delete.png" border="0" /></a></td>			</tr>			<tr><td colspan="2">&nbsp;</td></tr>			<tr>									<td align="left">Com endereço em:</td>			<td><textarea style="WIDTH: 300px; HEIGHT: 50px" class="form-control" name="LICENSA_COM_DE<?php echo $REL?>" id="LICENSA_COM_DE<?php echo $REL?>"><?php echo $COM_DE?></textarea></td>			</tr>			<tr><td colspan="2">&nbsp;</td></tr>			<tr>									<td align="left">Para:</td>			<td><input type="text" class="form-control" name="LICENSA_PARA<?php echo $REL?>" id="LICENSA_PARA<?php echo $REL?>" value="<?php echo $PARA?>" /></td>			</tr>			<tr><td colspan="2">&nbsp;</td></tr>			<tr>									<td align="left">Com endereço em:</td>			<td><textarea style="WIDTH: 300px; HEIGHT: 50px" class="form-control" name="LICENSA_COM_PARA<?php echo $REL?>" id="LICENSA_COM_PARA<?php echo $REL?>"><?php echo $COM_PARA?></textarea></td>			</tr>			<tr><td colspan="2">&nbsp;</td></tr>			<tr>									<td width="130" align="left">Número:</td>			<td align="left"><input type="text" class="form-control" name="LICENSA_NUMERO_BOLETIM<?php echo $REL?>" id="LICENSA_NUMERO_BOLETIM<?php echo $REL?>" value="<?php echo $NUMERO_BOLETIM;?>" class="LICENSA_NUMERO_BOLETIM" /></td>									</tr>						<tr><td colspan="2">&nbsp;</td></tr>			<tr>									<td align="left">Data Boletim:</td>			<td align="left">			<table cellpadding="0" cellspacing="0" border="0">			<tr>			<td><input type="text" name="LICENSA_DATA_BOLETIM<?php echo $REL?>" id="LICENSA_DATA_BOLETIM<?php echo $REL?>" class="box dropdate LICENSA_DATA_BOLETIM" value="<?php echo $DATA_BOLETIM?>" /></td>			<td align="right" align="left" width="100">Boletim PDF:</td>			<td align="left"><?php if($BOLETIM_EXT && file_exists('../../files/documentos/'.$BOLETIM_EXT)){ echo '<a class="pretourl_small fancybox2" href="../../files/documentos/'.$BOLETIM_EXT.'" target="_blank" class="url_reno">Abrir Ficheiro</a><br />';}?><input type="file" name="LICENSA_BOLETIM_EXT<?php echo $REL?>" id="LICENSA_BOLETIM_EXT<?php echo $REL?>" class="LICENSA_BOLETIM_EXT" /></td>			</tr>			</table>			</td>									</tr>			<tr><td style="border-bottom:#c0c0c0 1px solid" colspan="2">&nbsp;</td></tr>			<tr><td colspan="2">&nbsp;</td></tr>			</table>					<?php			$rs->db_next();		}	}		?>	<input type="hidden" name="total_linhas_licensa" id="total_linhas_licensa" value="<?php echo ($REL+1)?>" />	</div>	<table width="100%" cellpadding="0" cellspacing="0" border="0">	<tr>							<td width="30" align="left"><a href="#" onclick="return false;" class="addRow_licensa"><img src="img/add-item.png"></a></td>	<td align="left"><a href="#" onclick="return false;" class="pretourl addRow_licensa">Adicionar Licença</a></td>	</tr>	<tr><td colspan="2">&nbsp;</td></tr>	</table>	<div class="clearboth"></div>